/***
 * MARK: servingModelFor
 * @description THE single source of truth for "which model does this
 *   assignment serve?", shared verbatim by the Runner (`runner/daemon.js`,
 *   which reports it on the `prompted` progress event and inside the
 *   completion posture string) and the backend (`api/flow/`, re-exported
 *   through `api/flow/runnerPosture.js`) so the two can never drift.
 *
 *   Rules, in order:
 *   1. Non-LLM stage kinds (ci/script/deploy/command/merge/integrate/
 *      integration/human) serve NO model and report `null` — even if a
 *      model string arrives by accident. CI stages run a command, not an
 *      LLM, so inventing a model for them is a lie the UI would render.
 *   2. Otherwise the dispatched task's required model wins (`model`).
 *   3. Otherwise the Runner's configured default (`fallbackModel`) wins —
 *      that is the model the harness actually runs in single-assignment
 *      mode or for a model-less task.
 *   4. Otherwise `null`.
 *
 *   The `"default"` sentinel is NEVER returned: the rest of the engine
 *   uses `"default"` to mean "harness-managed, no pinned model" (blank
 *   stage pick), so reporting it would put the fake `default` pill back
 *   in the UI — the exact regression this helper exists to fix. `null`
 *   means "no model to report" and downstream (client body builder,
 *   posture formatter, ledger, UI pills) treats it as "omit the field".
 *   Blank/whitespace-only, non-string, and `"default"` inputs all count
 *   as absent, so a malformed dispatch answer or an operator who sets
 *   `KAINBAIN_RUNNER_MODEL=default` degrades to "no model" instead of
 *   leaking `"  "` or `"default"` into the UI. Kind matching is
 *   case-insensitive and trimmed.
 * @example servingModelFor({ kind: 'agent', model: 'kimi-k3:cloud', fallbackModel: 'x' }) => 'kimi-k3:cloud'
 * @example servingModelFor({ kind: 'agent', model: '', fallbackModel: 'runner-default' }) => 'runner-default'
 * @example servingModelFor({ kind: 'ci', model: 'anything', fallbackModel: 'x' }) => null
 * @example servingModelFor({ kind: 'agent', model: '   ', fallbackModel: '   ' }) => null
 * @example servingModelFor({ kind: 'agent', model: 'default', fallbackModel: 'x' }) => 'x'
 * @example servingModelFor({ kind: 'agent', model: 'default', fallbackModel: 'default' }) => null
 * @param {Object} [opts]
 * @param {string} [opts.kind] - Assignment kind (stage type, normalized by the backend: `ci` for ci/script/deploy/command, `merge`/`integrate` for merges).
 * @param {string} [opts.model] - Model required by the dispatched task (`requirements.model`).
 * @param {string} [opts.fallbackModel] - The Runner's configured default model (`config.model`).
 * @returns {string|null} The served model, or `null` when the assignment serves no LLM.
 ***/
export function servingModelFor(opts = {}) {
	// Total on hostile input: a non-object argument (null, a bare string)
	// reads as "nothing to serve" instead of throwing — this helper sits on
	// the dispatch wire, so it must never crash a Runner or route.
	const { kind, model, fallbackModel } =
		opts && typeof opts === "object" ? opts : {};
	// Stage kinds that never run an LLM. The backend normalizes
	// ci/script/deploy/command to `ci` before dispatch, but the raw types
	// are listed too so a hand-rolled or older dispatch answer still fails
	// safe (reports no model) instead of reporting one that is not in use.
	const nonLlmKinds = new Set([
		"ci",
		"script",
		"deploy",
		"command",
		"merge",
		"integrate",
		"integration",
		"human",
	]);
	const k = String(kind ?? "").trim().toLowerCase();
	if (nonLlmKinds.has(k)) return null;
	// A trimmed value counts as a served model unless it is blank, not a
	// string, or the engine-wide "default" sentinel (blank stage pick =
	// harness-managed, no pinned model). The sentinel check is
	// case-insensitive so "Default" can never render as a fake pill.
	const clean = (value) => {
		if (typeof value !== "string") return null;
		const trimmed = value.trim();
		if (!trimmed || trimmed.toLowerCase() === "default") return null;
		return trimmed;
	};
	const explicit = clean(model);
	if (explicit) return explicit;
	return clean(fallbackModel);
}
/***
 * MARK: formatPosture
 * @description Formats the Runner's `posture` string — the
 *   `tiers:harness:model` line stored in the execution history and shown
 *   in the UI. Shared verbatim by the Runner (`runner/daemon.js`) and the
 *   backend (`api/flow/runnerPosture.js`) so the wire format cannot drift.
 *
 *   The `:model` segment is appended ONLY when a real, non-blank model is
 *   served. CI / merge / integrate assignments pass `model: null` (see
 *   `servingModelFor`), so their posture is `T0:ci-harness` with NO
 *   trailing segment — never the Runner's default model and never the
 *   literal `"default"`, which used to leak into every CI stage's history.
 *   Consumers must therefore treat the model segment as optional; nothing
 *   parses posture by fixed segment count. Blank/whitespace or non-string
 *   values count as absent, and segments are joined only when present, so
 *   the string is always well-formed (`a:b:c`, `a:b`, `a`, or ``) rather
 *   than containing stray `::`, leading `:`, or `null` text. The
 *   engine-wide `"default"` sentinel (blank stage pick = harness-managed,
 *   no pinned model) also counts as absent — same rule as
 *   `servingModelFor`, the ledger ingest, and `formatModelRef`, so no
 *   caller can ever leak the fake `default` segment into a posture line.
 * @example formatPosture({ tiers: ['T0'], harness: 'pi', model: 'kimi-k3:cloud' }) => 'T0:pi:kimi-k3:cloud'
 * @example formatPosture({ tiers: ['T0', 'T1'], harness: 'pi', model: null }) => 'T0/T1:pi'
 * @example formatPosture({ tiers: ['T0'], harness: 'integration', model: '' }) => 'T0:integration'
 * @example formatPosture({ harness: 'pi', model: 'm' }) => 'pi:m'
 * @example formatPosture({ tiers: ['T0'], harness: 'pi', model: 'default' }) => 'T0:pi'
 * @param {Object} [opts]
 * @param {Array<string>|string} [opts.tiers] - Runner tiers; arrays join with `/`.
 * @param {string} [opts.harness] - Serving harness id (`integration` for merge jobs).
 * @param {string|null} [opts.model] - Served model, or `null` to omit the segment.
 * @returns {string} The posture string, model segment present only when real.
 ***/
export function formatPosture({ tiers, harness, model } = {}) {
	const tierPart = Array.isArray(tiers)
		? tiers.map((t) => String(t ?? "").trim()).filter(Boolean).join("/")
		: String(tiers ?? "").trim();
	const harnessPart = typeof harness === "string" ? harness.trim() : "";
	const trimmedModel = typeof model === "string" ? model.trim() : "";
	const cleanModel =
		trimmedModel && trimmedModel.toLowerCase() !== "default" ? trimmedModel : null;
	return [tierPart, harnessPart, cleanModel].filter(Boolean).join(":");
}
/***
 * MARK: modelAliases (shared alias grammar)
 * @description THE single implementation of the KainBain per-project model
 *   alias system, shared verbatim by the backend engine (`api/projectStore.js`,
 *   `api/agentRunner.js`, `api/sessionStore.js`) and the frontend settings UI
 *   (`frontend/src/components/settings/ModelAliasesSection.jsx`) so validation
 *   and resolution rules cannot drift. Plain ESM, zero dependencies.
 *
 *   An alias binds a short per-project name (e.g. `small`, `design`) to one
 *   or more weighted harness + model targets
 *   (`{ name, targets: [{ harness, model, percent }] }`, persisted on
 *   `project.modelAliases`; a legacy `{ name, harness, model }` record reads
 *   as one 100% target). Stages reference aliases through the
 *   existing harness-first fields — `harness: "alias"` + `model: "<name>"` —
 *   so every inherit/override path keeps working unchanged, and editing an
 *   alias changes every referencing stage with no stage edits (stages store
 *   the reference, never a copy of the concrete values).
 *
 *   `alias` is a VIRTUAL harness id: it never names a real AgentHarness
 *   (registering it throws — see `api/agent/harnessRegistry.js`), and an
 *   alias target pointing back at `alias` is a loop, treated as unknown.
 ***/

/** The virtual harness id that scopes alias references. Never a real harness. */
export const ALIAS_HARNESS_ID = "alias";

/** Alias names mirror the harness-id shape: lowercase, URL-safe. */
export const ALIAS_NAME_PATTERN = /^[a-z0-9][a-z0-9_-]*$/;

/** Maximum alias name length (keeps picker labels and logs readable). */
export const ALIAS_NAME_MAX_LENGTH = 64;

/***
 * MARK: normalizeAliasName
 * @description Trims an alias name to its usable form ("" when blank or
 *   non-string, i.e. "no alias named").
 * @example normalizeAliasName("  Small  ") => "Small"
 * @example normalizeAliasName("") => ""
 * @param {unknown} name - Raw alias name.
 * @returns {string} Trimmed name, or "" when unset.
 ***/
export function normalizeAliasName(name) {
	return typeof name === "string" ? name.trim() : "";
}

/***
 * MARK: validateAliasName
 * @description Validates an alias name, returning an error string or null.
 *   Names are trimmed, 1–64 chars, and must match `[a-z0-9][a-z0-9_-]*`
 *   (case-sensitive: `Small` and `small` are different aliases, and uppercase
 *   is rejected so references cannot drift by case).
 * @example validateAliasName("small") => null
 * @example validateAliasName("Small") => "…"
 * @param {unknown} name - Raw alias name.
 * @returns {string|null} Error message, or null when valid.
 ***/
export function validateAliasName(name) {
	const trimmed = normalizeAliasName(name);
	if (!trimmed) return "Alias name is required";
	if (trimmed.length > ALIAS_NAME_MAX_LENGTH) {
		return `Alias name must be at most ${ALIAS_NAME_MAX_LENGTH} characters`;
	}
	if (!ALIAS_NAME_PATTERN.test(trimmed)) {
		return "Alias name must start with a letter or digit and contain only lowercase letters, digits, - and _";
	}
	return null;
}

/***
 * MARK: validateAliasTarget
 * @description Validates ONE weighted target inside a multi-target alias,
 *   returning an error string or null. The target harness must be a
 *   non-empty string that is NOT the virtual `alias` id (loop guard). The
 *   target model is a string in any accepted model-key form (blank is
 *   allowed at the grammar level for self-managed `none` harnesses — the
 *   settings UI additionally requires a model for `list` harnesses). The
 *   percent is an integer 1–100 (the rows of one alias must sum to exactly
 *   100 — see `validateAliasTargets`).
 * @example validateAliasTarget({ harness: "pi", model: "google::m", percent: 90 }, "small") => null
 * @example validateAliasTarget({ harness: "pi", model: "m", percent: 0 }, "small") => "…"
 * @param {unknown} target - Candidate `{ harness, model, percent }` record.
 * @param {unknown} aliasName - Owning alias name (for error messages).
 * @returns {string|null} Error message, or null when valid.
 ***/
export function validateAliasTarget(target, aliasName) {
	const label =
		normalizeAliasName(aliasName) || "(unnamed alias)";
	if (!target || typeof target !== "object" || Array.isArray(target)) {
		return `Alias "${label}" has a target that must be an object { harness, model, percent }`;
	}
	const harness =
		typeof target.harness === "string" ? target.harness.trim() : "";
	if (!harness) return `Alias "${label}" has a target without a harness`;
	if (harness === ALIAS_HARNESS_ID) {
		return `Alias "${label}" cannot target the "${ALIAS_HARNESS_ID}" harness (aliases cannot point at aliases)`;
	}
	if (typeof target.model !== "string") {
		return `Alias "${label}" has a target without a model`;
	}
	if (
		typeof target.percent !== "number" ||
		!Number.isInteger(target.percent) ||
		target.percent < 1 ||
		target.percent > 100
	) {
		return `Alias "${label}" has a target whose percent must be a whole number from 1 to 100`;
	}
	return null;
}

/***
 * MARK: validateAliasTargets
 * @description Validates a whole multi-target split: a non-empty array whose
 *   every target satisfies `validateAliasTarget` and whose percents sum to
 *   exactly 100 (users see percentages, never arbitrary weights).
 * @example validateAliasTargets([{ harness: "pi", model: "m", percent: 90 }, { harness: "custom", model: "", percent: 10 }], "small") => null
 * @param {unknown} targets - Candidate targets array.
 * @param {unknown} aliasName - Owning alias name (for error messages).
 * @returns {string|null} Error message, or null when valid.
 ***/
export function validateAliasTargets(targets, aliasName) {
	const label =
		normalizeAliasName(aliasName) || "(unnamed alias)";
	if (!Array.isArray(targets) || targets.length === 0) {
		return `Alias "${label}" needs at least one target`;
	}
	for (const target of targets) {
		const reason = validateAliasTarget(target, aliasName);
		if (reason) return reason;
	}
	const total = targets.reduce((sum, t) => sum + t.percent, 0);
	if (total !== 100) {
		return `Alias "${label}" splits ${total}% — Percents must add up to 100%`;
	}
	return null;
}

/***
 * MARK: validateModelAlias
 * @description Validates one alias record, returning an error string or null.
 *   Two shapes are accepted: the legacy single-target record
 *   (`{ name, harness, model }`, read as one 100% target) and the weighted
 *   record (`{ name, targets: [{ harness, model, percent }] }` whose
 *   percents sum to 100). A lone target harness must be a non-empty string
 *   that is NOT the virtual `alias` id (loop guard); the model accepts any
 *   model-key form, EXCEPT blank is allowed only for self-managed harnesses
 *   at dispatch (the settings UI requires a model for `list` harnesses).
 * @example validateModelAlias({ name: "small", harness: "pi", model: "google::m" }) => null
 * @example validateModelAlias({ name: "c", harness: "custom", model: "" }) => null
 * @param {unknown} entry - Candidate alias record.
